const S10_PATTERN = /^[A-Z]{2}(\d{8})(\d)AT$/;
const S10_WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** UPU S10 check digit for the 8 serial digits (see docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  const sum = [...serial].reduce((acc, d, i) => acc + Number(d) * S10_WEIGHTS[i], 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

export type S10Result = 'ok' | 'bad_format' | 'bad_check_digit';

/** Validates an Austrian Post S10 number such as RR123456785AT (expects upper case). */
export function checkAtpTrackingNumber(value: string): S10Result {
  const match = S10_PATTERN.exec(value);
  if (!match) return 'bad_format';
  return s10CheckDigit(match[1]) === Number(match[2]) ? 'ok' : 'bad_check_digit';
}
